package ai.decisionos.aside;
import android.content.*;import android.net.Uri;import android.os.Bundle;import org.json.*;import java.util.concurrent.atomic.AtomicReference;
/** Downloads only the synthetic campus report requested by this verification. */
final class CampusArtifactsLiveChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();try{
  JSONObject goal=null,document=null;try(GoalStore store=new GoalStore(i.getTargetContext())){for(JSONObject g:store.goals()){if(!g.optString("character").equals("grades"))continue;JSONArray history=g.optJSONArray("chatMessages");if(history==null)continue;for(int n=history.length()-1;n>=0;n--){JSONObject m=history.getJSONObject(n);if("completed".equals(m.optString("state"))&&m.has("document")){goal=g;document=m.getJSONObject("document");break;}}if(document!=null)break;}}
  if(document==null)throw new AssertionError("Synthetic live report artifacts required");
  String id=goal.getString("id");GoalAgentActivity a=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("goal_id",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));i.waitForIdleSync();
  JSONObject doc=document;JSONArray files=doc.getJSONObject("manifest").getJSONArray("files");i.check(files.length()==2,"two generated artifacts");
  Uri preview=null;String previewName="";
  for(int n=0;n<files.length();n++){JSONObject file=files.getJSONObject(n);String name=file.getString("name");i.check(name.endsWith(".docx")||name.endsWith(".pptx"),"expected export format");AtomicReference<JSONObject> reply=new AtomicReference<>();i.runOnMainSync(()->a.relay.document(doc.optString("job_id"),doc.optString("goalId",id),name,file.optString("sha256"),reply::set));for(int wait=0;wait<60&&reply.get()==null;wait++)Thread.sleep(500);if(reply.get()==null||reply.get().has("error"))throw new AssertionError("artifact download failed: "+reply.get());Uri uri=Uri.parse(reply.get().getString("uri"));CampusDocumentExport.validate(a,uri);i.check(true,"downloaded artifact SHA256 verified");if(name.endsWith(".docx")){preview=uri;previewName=name;try(java.io.InputStream in=a.getContentResolver().openInputStream(uri)){String text=CompanionDocumentPreview.read(in);i.check(text.contains("과제 마감일"),"DOCX source content preserved");}}}
  Uri selected=preview;String name=previewName;i.runOnMainSync(()->a.chat.companion.previewDocument(selected,name));i.waitForIdleSync();Thread.sleep(2000);
  android.graphics.Bitmap screenshot=i.getUiAutomation().takeScreenshot();try(java.io.OutputStream stream=new java.io.FileOutputStream(new java.io.File(a.getCacheDir(),"campus-report-preview.png"))){screenshot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,stream);}screenshot.recycle();
  if(i.scenario.containsKey("campusDrivePicker")){long began=System.currentTimeMillis();android.content.SharedPreferences pending=a.getSharedPreferences(CampusDocumentExport.PREF,0);if(pending.getString("source","").equals(selected.toString()))pending.edit().clear().commit();String exportName=name.replace(".docx","-verify-"+System.nanoTime()+".docx");i.runOnMainSync(()->CampusDocumentExport.start(a,selected,exportName));selectDrive(i,i.scenario.getString("driveAccount",""));boolean saved=false;for(int wait=0;wait<240;wait++){Thread.sleep(500);android.content.SharedPreferences receipt=a.getSharedPreferences("campus_export_receipts",0);if(receipt.getLong("verified_at",0)>=began){i.check(receipt.getString("source_sha256","").equals(selected.getLastPathSegment().substring(0,64)),"selected provider exact hash");out.putString("provider",receipt.getString("provider",""));saved=true;break;}}if(!saved)throw new AssertionError("Document provider selection or readback not completed");}
  out.putString("stream","PASS "+i.checks+" real chat document downloads, hash and DOCX in-app preview checks\n");
 }catch(Throwable error){out.putString("stream","FAIL "+error+"\n");}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
 static boolean click(android.view.accessibility.AccessibilityNodeInfo node){for(int n=0;n<6&&node!=null;n++,node=node.getParent())if(node.isClickable()&&node.isEnabled()&&node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK))return true;return false;}
 static boolean text(GoalInstrumentation i,String wanted){android.view.accessibility.AccessibilityNodeInfo root=i.getUiAutomation().getRootInActiveWindow();if(root==null)return false;for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(wanted))if(wanted.contentEquals(node.getText()==null?"":node.getText())&&click(node))return true;return false;}
 static void shell(GoalInstrumentation i,String command)throws Exception{try(android.os.ParcelFileDescriptor fd=i.getUiAutomation().executeShellCommand(command);java.io.InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(fd)){byte[] buffer=new byte[1024];while(in.read(buffer)!=-1){}}}
 static void selectDrive(GoalInstrumentation i,String account)throws Exception{
  if(account.isEmpty())return;boolean picker=false;for(int wait=0;wait<40;wait++){Thread.sleep(500);android.view.accessibility.AccessibilityNodeInfo active=i.getUiAutomation().getRootInActiveWindow();if(active!=null&&String.valueOf(active.getPackageName()).contains("documentsui")){picker=true;break;}}if(!picker)throw new AssertionError("System document picker not foreground");
  // Open the system provider drawer. No account credentials are read.
  android.view.accessibility.AccessibilityNodeInfo root=i.getUiAutomation().getRootInActiveWindow();boolean opened=false;
  java.util.ArrayDeque<android.view.accessibility.AccessibilityNodeInfo> nodes=new java.util.ArrayDeque<>();if(root!=null)nodes.add(root);
  while(!nodes.isEmpty()){android.view.accessibility.AccessibilityNodeInfo node=nodes.remove();String desc=String.valueOf(node.getContentDescription());if(desc.contains("탐색")||desc.equals("Show roots")||desc.contains("위치 표시")){if(click(node)){opened=true;break;}}for(int n=0;n<node.getChildCount();n++)if(node.getChild(n)!=null)nodes.add(node.getChild(n));}
  if(opened)Thread.sleep(800);if(!opened){shell(i,"input tap 78 150");Thread.sleep(500);}
  boolean selected=false;for(int n=0;n<15;n++){if(text(i,account)){selected=true;break;}shell(i,"input swipe 350 2000 350 650 400");Thread.sleep(500);}if(!selected){android.graphics.Bitmap shot=i.getUiAutomation().takeScreenshot();try(java.io.OutputStream stream=new java.io.FileOutputStream(new java.io.File(i.getTargetContext().getCacheDir(),"drive-picker-failure.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,stream);}shot.recycle();throw new AssertionError("Requested Drive account not visible");}Thread.sleep(1800);
  if(!text(i,"내 드라이브")&&!text(i,"My Drive"))throw new AssertionError("My Drive unavailable");Thread.sleep(1500);if(!text(i,"저장")&&!text(i,"Save"))throw new AssertionError("Save unavailable");
 }

}
